"use strict";

var _graphqlRelay = require("graphql-relay");
var _SendEmailDialog = require("../SendEmailDialog.utils");
describe('deleteFromState', function () {
  it('returns object with key/value deleted', function () {
    var state = {
      church: 'sarge',
      donut: 'tucker',
      caboose: 'grif',
      sheila: 'tex'
    };
    expect((0, _SendEmailDialog.deleteFromState)(state, 'donut')).toEqual({
      church: 'sarge',
      caboose: 'grif',
      sheila: 'tex'
    });
  });
});
describe('getFormattedRecipientData', function () {
  it('should return combined formatted array', function () {
    var rolesData = [{
      id: 'Um9sZTowMDAwMDAyMDE1OWIyZTMxYzM4NGRkMDYyODhhYmY1Zg==',
      isActive: true,
      name: 'role1'
    }, {
      id: 'Um9sZTowMDAwMDAyMDE1OWIyZTMyZGMxMmViZTNlODJiMzQ4Mw==',
      isActive: true,
      name: 'role2'
    }, {
      id: 'Um9sZTowMDAwMDAyMDE1OWIyZTM1Y2VkZGJiYzY0MDdjN2ZmNQ==',
      isActive: false,
      name: 'role3'
    }];
    var peopleData = [{
      id: 'UGVyc29uOjAwMDAwMDIwMTU5YjZhZmRhOGNkZGZhMzE0Y2RjNDE4',
      firstName: 'Tom',
      isActive: true,
      lastName: 'Hanks'
    }, {
      id: 'UGVyc29uOjAwMDAwMDIwMTU5YjZiMjIzMGIyNTA0NWJiN2NjNjQ0',
      firstName: 'Rita',
      isActive: true,
      lastName: 'Wilson'
    }, {
      id: 'UGVyc29uOjAwMDAwMDIwMTU5YjZiMmVhYjA3YmE1OTc5MDJhYjg0',
      firstName: 'Idris',
      isActive: false,
      lastName: 'Elba'
    }];
    var expectedResult = [{
      label: rolesData[0].name,
      type: 'Role',
      value: (0, _graphqlRelay.fromGlobalId)(rolesData[0].id).id
    }, {
      label: rolesData[1].name,
      type: 'Role',
      value: (0, _graphqlRelay.fromGlobalId)(rolesData[1].id).id
    }, {
      label: "".concat(peopleData[0].firstName, " ").concat(peopleData[0].lastName),
      type: 'User',
      value: (0, _graphqlRelay.fromGlobalId)(peopleData[0].id).id
    }, {
      label: "".concat(peopleData[1].firstName, " ").concat(peopleData[1].lastName),
      type: 'User',
      value: (0, _graphqlRelay.fromGlobalId)(peopleData[1].id).id
    }];
    expect((0, _SendEmailDialog.getFormattedRecipientData)(rolesData, peopleData)).toEqual(expectedResult);
  });
  it('should return empty array if no data', function () {
    var rolesData = null;
    var peopleData = null;
    expect((0, _SendEmailDialog.getFormattedRecipientData)(rolesData, peopleData)).toEqual([]);
  });
});